from pathlib import Path

def read_upload(root, filename):
    path = Path(root) / filename
    return path.read_text()

def export_rows(path, rows):
    handle = open(path, 'w')
    for row in rows:
        handle.write(','.join(row) + '\n')
    return len(rows)

